SELECT t1.dept_id as deptId ,t1.parent_id as parentId,t1.ancestors as ancestors,t1.dept_name as deptName, t1.order_num as orderNum,t1.leader as leader,t1.phone as phone,t1.email as email,t1.status as status, t1.del_flag as delFlag, t1.create_by as createBy,t1.create_time as createTime,t1.update_by as updateBy ,t1.update_time as updateTime,t2.dept_name as parentName FROM `tb_dept` t1 LEFT JOIN tb_dept t2 on t1.parent_id = t2.dept_id WHERE t1.del_flag = '1'
AND t1.dept_name like concat('%', #{deptDto.deptName}, '%')
AND t1.status = #{deptDto.status}

SELECT count(*)
FROM `tb_dept`
WHERE parent_id = #{parentId} and dept_name = #{deptName}

SELECT dept_name
FROM `tb_dept`
WHERE parent_id = #{parentId} AND dept_id <> #{deptId}

SELECT dept_id as deptId ,parent_id as parentId,ancestors as ancestors,dept_name as deptName, order_num as orderNum,leader as leader,phone as phone,email as email,status as status,del_flag as delFlag, create_by as createBy,create_time as createTime,update_by as updateBy ,update_time as updateTime FROM `tb_dept` WHERE del_flag = '1'
AND dept_name like concat('%', #{deptDto.deptName}, '%')
AND status = #{deptDto.status}

SELECT dept_id as deptId
FROM tb_dept
WHERE parent_id = #{deptId1}
